-- +goose Up
CREATE TABLE IF NOT EXISTS public.notifications (
    id uuid NOT NULL,
    user_id uuid NOT NULL,
    type text NOT NULL,
    title text NOT NULL,
    body text,
    link text,
    source_job_id uuid,
    read_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP
);

-- +goose StatementBegin
DO $$ BEGIN
    IF NOT EXISTS (SELECT 1 FROM pg_constraint
                   WHERE conname = 'notifications_pkey'
                     AND conrelid = 'public.notifications'::regclass) THEN
        ALTER TABLE ONLY public.notifications
            ADD CONSTRAINT notifications_pkey PRIMARY KEY (id);
    END IF;
EXCEPTION WHEN duplicate_object OR duplicate_table OR invalid_table_definition THEN NULL;
END $$;
-- +goose StatementEnd

CREATE INDEX IF NOT EXISTS idx_notif_user_created ON public.notifications USING btree (user_id, created_at DESC);

CREATE UNIQUE INDEX IF NOT EXISTS idx_notif_user_source ON public.notifications USING btree (user_id, source_job_id) WHERE (source_job_id IS NOT NULL);

CREATE INDEX IF NOT EXISTS idx_notif_user_unread ON public.notifications USING btree (user_id) WHERE (read_at IS NULL);

